package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamRhythmCreativeBank1 {
    private const val T = "නර්තනයේ රිද්මය, තාල ශාස්ත්‍රය, නව නිර්මාණ හා වෘත්තීය අගය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("නර්තනයේ හා සංගීතයේ කාලය මැන ගන්නා මූලික ඒකකය හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "මාත්‍රාව", "රසය", "අභිනය", "මුද්‍රාව", "හෘද ස්පන්දනයක් හෝ නිමේෂයක් බඳු කාල ප්‍රමාණය මාත්‍රාවක් ලෙස සැලකේ."),
        q("මාත්‍රා කිහිපයක් අතර පවතින ඒකාකාරී කාල වේගය නර්තන ශාස්ත්‍රයේදී හඳුන්වන්නේ කුමන නමකින්ද?", "ලය", "භාවය", "වේෂය", "හැඩය", "ලය මඟින් නර්තනයක මන්දගාමී, මධ්‍යම හෝ වේගවත් ගමන් වේගය තීරණය වේ."),
        q("නර්තන විද්‍යාවේ එන ප්‍රධාන ලය වර්ග තුන කවරේද?", "විලම්බ ලය, මධ්‍ය ලය සහ ද්‍රුත ලය", "තාණ්ඩව, ලස්ය සහ සාත්වික", "ආතත, විතත සහ ඝන", "පද, අඩව් සහ කස්තිරම්", "විලම්බ යනු මන්දගාමී ලයයි, මධ්‍ය යනු සාමාන්‍ය ලයයි, ද්‍රුත යනු වේගවත් ලයයි."),
        q("ඉතා සෙමින් ගමන් කරන මන්දගාමී කාල වේගය හඳුන්වන්නේ කුමන ලය ලෙසද?", "විලම්බ ලය", "ද්‍රුත ලය", "මධ්‍ය ලය", "අතිද්‍රුත ලය", "විලම්බ ලයේදී මාත්‍රා අතර කාල පරතරය වැඩි වන අතර ශෝක, භක්ති වැනි භාව ප්‍රකාශයට උචිතය."),
        q("විලම්බ ලය මෙන් දෙගුණයක වේගයකින් පවතින සාමාන්‍ය කාල වේගය කුමක්ද?", "මධ්‍ය ලය", "විලම්බ ලය", "ද්‍රුත ලය", "සුළු ලය", "සාමාන්‍ය පාද තැබීම් හා බොහෝ වන්නම් ආරම්භ වන්නේ මධ්‍ය ලයෙනි."),
        q("මධ්‍ය ලය මෙන් දෙගුණයක වේගයකින් යුක්තව අඩව් හා කස්තිරම් අවසන් කිරීමට බහුලව යොදන ලය කුමක්ද?", "ද්‍රුත ලය", "විලම්බ ලය", "සම ලය", "නිශ්චල ලය", "ද්‍රුත ලයේදී නර්තන ශිල්පියාගේ ජවසම්පන්න හා වේගවත් හැකියාවන් කැපී පෙනේ."),
        q("දේශීය නර්තනයේදී 'තාලය' යනු කුමක්ද?", "නියමිත මාත්‍රා ගණනකට අනුව සැකසුණු රිද්ම රටාවකි", "වේදිකාවේ ආලෝක වර්ණයකි", "නැටුම් ඇඳුමේ කොටසකි", "වෙස්මුහුණේ වර්ගයකි", "තාලය විසින් සංගීතය හා නර්තනය පිළිවෙළකට හා ඒකාග්‍රතාවයකට බැඳ තබයි."),
        q("තාලයක සියලුම මාත්‍රා එක් වටයක් ගමන් කර නැවත පළමු මාත්‍රාවට පැමිණීම හඳුන්වන්නේ කෙසේද?", "ආවර්තනයක්", "මාත්‍රාවක්", "ඛාලියක්", "විලම්බයක්", "තාල චක්‍රයේ එක් සම්පූර්ණ වටයක් ආවර්තනයක් හෙවත් පද වටයක් ලෙස හැඳින්වේ."),
        q("තාල ආවර්තනයක ආරම්භක පළමු මාත්‍රාව හෙවත් මුල්ම බර තැබීම හඳුන්වන්නේ කුමන නමකින්ද?", "සම", "ඛාලි", "විභාග", "ද්‍රුත", "කස්තිරමක් හෝ තීර්මානමක් අවසන් කරනු ලබන්නේ තාලයේ 'සම' ස්ථානයට පැමිණීමෙනි."),
        q("දේශීය නර්තන ශාස්ත්‍රයේ භාවිත වන 'සුළු ගැළ' (මධ්‍ය දෙතිත) තාලය සමන්විත මාත්‍රා ගණන කීයද?", "මාත්‍රා 2 කි", "මාත්‍රා 3 කි", "මාත්‍රා 4 කි", "මාත්‍රා 7 කි", "දෙතිත හෙවත් සුළු ගැළ මාත්‍රා දෙකේ තාල රටාවක් ලෙස මූලික පුහුණුවේදී භාවිත වේ."),
        q("දේශීය නර්තන සම්ප්‍රදායේ 'මැදුම් ගැළ' (මධ්‍ය තුන්තිත) තාලයේ මුළු මාත්‍රා ගණන කීයද?", "මාත්‍රා 3 කි", "මාත්‍රා 2 කි", "මාත්‍රා 5 කි", "මාත්‍රා 8 කි", "තත් දිත් තොං යනුවෙන් ගැයෙන තුන්තිත මාත්‍රා තුනකින් යුක්ත වේ."),
        q("උඩරට නර්තනයේ 'මහා ගැළ' හෙවත් සිව්තිත තාලයේ මාත්‍රා සංඛ්‍යාව කීයද?", "මාත්‍රා 4 කි", "මාත්‍රා 3 කි", "මාත්‍රා 6 කි", "මාත්‍රා 9 කි", "මාත්‍රා හතර බැගින් වූ සරල සිව්තිත තාලය සඳහා ගජගා වන්නම වැනි නැටුම් පදනම් වේ."),
        q("මධ්‍යම ප්‍රමාණයේ සුළු තනම තාලයේ මාත්‍රා බෙදීම කුමන ආකාරයේද?", "මාත්‍රා 3 බැගින් හෝ 2+3 ආකාරයේ පංච මාත්‍රා රටාවකි", "මාත්‍රා 16 ක ත්‍රි තාලයකි", "මාත්‍රා 10 ක ඣප් තාලයකි", "මාත්‍රා 14 ක ධමාර් තාලයකි", "තනම තාල වන්නම්වල මාත්‍රා සංකලනය අනුව තිත් කිහිපයකින් බෙදී යයි."),
        q("පහතරට නර්තනයේ 'තෙල්මේ නැටුම' සඳහා භාවිත කරන ප්‍රධාන තාලය හඳුන්වන්නේ කෙසේද?", "තෙල්මේ තාලය", "සුරඹා තාලය", "හේවිසි තාලය", "දාද්රා තාලය", "තෙල්මේ නැටුමේ ප්‍රධාන වට්ටම් වාදනය කරනු ලබන්නේ ආවේණික තෙල්මේ තාලයට අනුවය."),
        q("පහතරට සහ සබරගමු නර්තනවලදී තාලය ප්‍රකාශ කිරීමට තාලම්පට ගැසීමේදී දැකිය හැකි ප්‍රධාන ශබ්ද දෙක මොනවාද?", "වසා ගැසීම (ත) සහ හැර ගැසීම (ති)", "ගුං සහ දොං", "තත් සහ නං", "ජිං සහ කුඳ", "තාලම්පට යුගලය තදින් වසා හා නිදහස්ව හැර වාදනය කිරීමෙන් තිත් ස්ථාන සලකුණු කරයි."),
        q("දේශීය නර්තන සම්ප්‍රදායේ 'තිත' යන වචනයෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "තාලම්පට ගසා දක්වන මාත්‍රා බර තැබීමේ ස්ථානය", "වෙස්මුහුණේ ඇති ඉරක්", "නැටුම් කණ්ඩායමේ නායකයා", "වේදිකාවේ පිටවීමේ දොරටුව", "තිත යනු තාල රටාවක ප්‍රධාන ආරම්භක හා බෙදුම් ස්ථාන පෙන්වන තාලම්පට නාදයයි."),
        q("උඩරට නර්තනයේ සාම්ප්‍රදායික 'තාල පද්ධතිය' හැඳින්වීමේදී භාවිත කරන සිංහල තාල නාමයක් නොවන්නේ කුමක්ද?", "රුපක් තාලය", "සුළු තනම", "මැදුම් තනම", "මහා තනම", "සුළු තනම, මැදුම් තනම, සුළු මැදුම් තනම හා මහා තනම දේශීය තාල නාම වන අතර රුපක් යනු හින්දුස්ථානි තාලයකි."),
        q("වන්නම්වලදී 'තානම' ගැයීමෙන් පසු පළමු කවිය නැටීමේදී තාලය ආරම්භ කරන්නේ කෙසේද?", "තාලම්පට තිත සමඟ බෙර වාදනයට එක්වෙමින්", "කවිය අවසන් වූ පසු නිහඬව සිටිමින්", "බෙරය ඉවතට ගෙන", "තනිවම අත්පුඩි ගසමින්", "නිදහස් තාලයෙන් ගයන තානමට පසුව නිශ්චිත තිත හා තාලයට කවිය හා මාත්‍රා නැටේ."),
        q("සරඹ පුහුණුවේදී කාල මාත්‍රා මැන ගැනීම සඳහා ගුරුවරයා දඬියම් කඳට හෝ තාලම්පටට පහර දෙන්නේ කුමක් සඳහාද?", "සිසුන්ගේ පාද චලන ඒකාකාරී තාලයකට හුරු කිරීමට", "ශබ්දය වැඩි කිරීමට පමණක්", "සිසුන් බිය ගැන්වීමට", "කාමරය උණුසුම් කිරීමට", "ලය නොකැඩී තබා ගැනීම හා නිවැරදි තාල අවබෝධය ලබා ගැනීම සඳහා මෙය අත්‍යවශ්‍ය වේ."),
        q("දේශීය නර්තනයේ 'මාත්‍රා' හතරක් හඳුනා ගැනීමේදී 'තත් තත් දිත් තොං' යන බෙර පදය ගැනෙන්නේ කුමන අවස්ථාවටද?", "පාද හා අත් චලන තාලයට ගැළපීමේ මූලික අභ්‍යාසවලට", "නාට්‍ය දෙබස් කීමට", "වෙස්මුහුණු පින්තාරු කිරීමට", "ප්‍රේක්ෂකයන් පිටව යන විට", "නර්තන මාත්‍රා හා බෙර අක්ෂර එකට බැඳී පවතින බැවින් පද මතකය තාලය රැකීමට උදව් වේ."),
        q("නර්තනයේදී 'පද තැබීම' යන සංකල්පයෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "තාලයට අනුව නිශ්චිත බෙර අක්ෂර සමූහයකට දෙපා හා අංග චලනය කිරීම", "නැටුම ආරම්භ කිරීමට පෙර වේදිකාව අසල පාවහන් පෙළට තබා ගැනීම", "පෙරහුරු අවසන් වූ පසු සටහන් පොතක බෙර පද ලියා තැබීම", "පූජා මණ්ඩපයේ පහන් පැල අසල මල් හා පහන් දල්වා තැබීම", "පද තැබීම නිවැරදි නොවුණහොත් බෙර වාදනය හා නැටුම අතර සම්බන්ධය බිඳී යයි."),
        q("එකම තාලය තුළ සිට වේගය දෙගුණ කිරීම හෝ තුන්ගුණ කිරීම හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "ලය පෙරළිය හෙවත් කාල බෙදීම", "තානම් කීම", "වන්නම් මාරුව", "අභිනය වෙනස", "එකම තාල වේගය නොවෙනස්ව තබා එක් මාත්‍රාවක් තුළ පියවර දෙකක් හෝ හතරක් තැබීම දුගුන් හා චෞගුන් වැනි ක්‍රමවේද වේ."),
        q("නව නර්තන නිර්මාණයක් කිරීමේදී මූලිකවම අවධානය යොමු කළ යුතු පළමු පියවර කුමක්ද?", "තේමාවක් හා කතා සංකල්පයක් තෝරා ගැනීම", "ප්‍රසංග පෝස්ටර් ඇලවීම පමණි", "වේදිකාව සෝදා පිරිසිදු කිරීම", "අවසන් ජයග්‍රහණ නිවේදනය කිරීම", "සාර්ථක නර්තන නිර්මාණයක් ගොඩනැගෙන්නේ පැහැදිලි තේමාවක් හා අරමුණක් මතය."),
        q("නර්තන නිර්මාණකරණයේදී 'රංග අවකාශය' (Stage Space) නිවැරදිව කළමනාකරණය කිරීම යනු කුමක්ද?", "වේදිකාවේ ඉදිරි, මැද, පසු සහ පාර්ශ්ව කොටස් සමතුලිතව භාවිත කිරීම", "වේදිකාවේ එක් මුල්ලක පමණක් නැටීම", "වේදිකාවෙන් පිටත සිට නැටීම", "වේදිකාවේ තිරය වසා තැබීම", "නැටුම් කණ්ඩායමේ චලන හා හැඩතල ප්‍රේක්ෂකයාට ආකර්ෂණීය ලෙස පෙනෙන පරිදි අවකාශය යොදාගත යුතුය."),
        q("වේදිකා නර්තන නිර්මාණයකදී 'සමූහ රටා' (Formations) නිර්මාණය කිරීමෙන් ලැබෙන ප්‍රධානම අලංකාරය කුමක්ද?", "දෘශ්‍ය විවිධත්වය, සංවිධානාත්මක බව සහ හැඟීම් ප්‍රබලව දැක්වීම", "ශිල්පීන් ගණන අඩු කර ගැනීම", "බෙර හඬ නැවැත්වීම", "විදුලි බලය ඉතිරි කිරීම", "රේඛා, වෘත්ත, ත්‍රිකෝණ හා විකර්ණ රටා මඟින් නර්තනයට ජීවමාන චිත්‍රමය ස්වරූපයක් ලැබේ."),
        q("වේදිකාවේ මැද සිට ප්‍රේක්ෂකයා දෙසට ගමන් කරන සරල රේඛා හෝ විකර්ණ රටා මඟින් බොහෝ විට ඉස්මතු කරන්නේ කුමක්ද?", "ප්‍රබල බව, වීරත්වය සහ ආකර්ෂණීය ආමන්ත්‍රණය", "සැඟවී සිටීම", "නින්ද සහ විවේකය", "රංගනයේ අවසානය", "විකර්ණ හා ඉදිරි ගමන් වේදිකා ශක්තිය ප්‍රේක්ෂකාගාරය වෙත සෘජුව රැගෙන යයි."),
        q("නව නිර්මාණාත්මක නර්තනයකදී සාම්ප්‍රදායික ඇඳුම් වෙනුවට තේමාවට ගැළපෙන රංග වස්ත්‍ර භාවිතයේදී සැලකිය යුතු මූලික කරුණ කුමක්ද?", "ශරීර චලනවලට බාධාවක් නොවන පහසුව හා තේමාත්මක ගැළපීම", "හැකිතාක් බර වැඩි රෙදි භාවිතය", "චලන වැළැක්වෙන සේ තදින් ඇඳීම", "වර්ණ ගැළපීම නොසලකා හැරීම", "රංග වස්ත්‍ර ශිල්පියාගේ චලන නිදහස රකින අතරම ආලෝකය යටතේ අලංකාර විය යුතුය."),
        q("නර්තන නිර්මාණයකදී 'වේදිකා ආලෝකකරණය' මගින් ඉටු කරන ප්‍රධාන කලාත්මක කාර්යය කුමක්ද?", "අවස්ථාවට ගැළපෙන මනෝභාවය, කාලය සහ ස්ථානය මැවීම", "ශිල්පීන්ගේ බර අඩු කිරීම", "වෙස්මුහුණු සේදීම", "තාලය වෙනස් කිරීම", "රතු ආලෝකය කෝපය හෝ ගින්නද නිල් ආලෝකය රාත්‍රිය හෝ සාමයද නිරූපණයට උදව් වේ."),
        q("නූතන නිර්මාණාත්මක නර්තනයක් සඳහා සංගීතය සැලසුම් කිරීමේදී වඩාත් වැදගත් වන්නේ කුමක්ද?", "නර්තන චලනවල රිද්මයට හා භාවයට සංගීතය අනුකූල වීම", "අතිශයින් ඝෝෂාකාරී ශබ්ද පමණක් යෙදීම", "තේමාවට නොගැළපෙන ගීත එක් කිරීම", "සංගීතය සම්පූර්ණයෙන්ම ඉවත් කිරීම", "නැටුම හා සංගීතය අතර අන්‍යෝන්‍ය සබැඳියාව නිර්මාණයේ සාර්ථකත්වය තීරණය කරයි."),
        q("සම්ප්‍රදායික නර්තන අංග ඇසුරෙන් නව නිර්මාණ බිහි කිරීමේදී ශිල්පියෙකු අනුගමනය කළ යුතු නිවැරදි ප්‍රතිපත්තිය කුමක්ද?", "සම්ප්‍රදායේ මූලික අනන්‍යතාවට හානි නොකර නිර්මාණශීලීව ඉදිරිපත් කිරීම", "පැරණි සම්ප්‍රදාය සම්පූර්ණයෙන් හෙළා දැකීම", "වෙස් ඇඳුම අගෞරවනීය ලෙස විකෘති කිරීම", "තාලය හා පද නොසලකා හැරීම", "පාරම්පරික මූලධර්ම ගරු කරමින් නූතන ප්‍රේක්ෂක රසවින්දනයට ගැළපෙන සේ නිර්මාණ කළ යුතුය."),
        q("ශ්‍රී ලංකාවේ නූතන නර්තන හා මුද්‍රා නාට්‍ය ක්ෂේත්‍රයේ පුරෝගාමී යුගලය වූ චිත්‍රසේන හා වජිරා ශිල්පීන් විසින් කළ විශේෂ මෙහෙවර කුමක්ද?", "දේශීය උඩරට නැටුම් ආශ්‍රයෙන් නූතන වේදිකා මුද්‍රා නාට්‍ය කලාව බිහි කිරීම", "පහතරට කෝලම් වෙස්මුහුණු කැපීමේ වැඩමුළු පමණක් ආරම්භ කිරීම", "බටහිර සම්භාව්‍ය පියානෝ හා වයලීන් සංගීතය පමණක් ඉගැන්වීම", "සාම්ප්‍රදායික ගැමි නැටුම් වේදිකාවෙන් සම්පූර්ණයෙන් ඉවත් කිරීම", "චිත්‍රසේන සහ වජිරා ශ්‍රී ලාංකේය නර්තනය ජාත්‍යන්තර වේදිකාවට ගෙන යාමට මූලික වූහ."),
        q("ශ්‍රී ලාංකේය සම්ප්‍රදායික නර්තනයේ 'ගුරු කුල' හා ශාස්ත්‍රීය සටහන් ග්‍රන්ථාරූඪ කිරීමට පුරෝගාමී වූ විද්වතා කවුද?", "ජේ.ඊ. සේදරමන් මහතා", "ඩී.එස්. සේනානායක මහතා", "මාර්ටින් වික්‍රමසිංහ මහතා", "පණ්ඩිත් අමරදේව", "ජේ.ඊ. සේදරමන් මහතා උඩරට නැටුම් කලාව හා සබරගමු නැටුම් පිළිබඳ වටිනා ග්‍රන්ථ රචනා කළේය."),
        q("උඩරට වෙස් නර්තනය ලොව පුරා ප්‍රකට කිරීමට සමත් වූ ප්‍රවීණ නර්තන ශිල්පියා වන නිත්තවෙල ගුණයා ගුරුන්නාන්සේ ප්‍රසිද්ධියට පත්වූයේ කුමක් සඳහාද?", "ගජගා වන්නම හා උඩරට වෙස් නැටුම අද්විතීය ලෙස රංගනය කිරීම", "පහතරට සන්නි මුහුණු කැපීම", "බැලේ නැටුම් පුහුණු කිරීම", "හින්දුස්ථානි සිතාර් වාදනය", "නිත්තවෙල ගුණයා ගුරුන්නාන්සේ උඩරට නැටුමේ ජවය හා අභිමානය ජාත්‍යන්තරයට ගෙන ගියේය."),
        q("දේශීය නර්තන කලාව පාසල් විෂය මාලාවට සහ සෞන්දර්ය අධ්‍යාපනයට විධිමත්ව එක් කිරීමට පුරෝගාමී වූ කලාකරුවා කවුද?", "එස්. පණීභාරත මහතා", "එඩ්වින් සමරදිවාකර මහතා", "ඩබ්.එම්. පෙරේරා මහතා", "ජෝන් ද සිල්වා මහතා", "පණීභාරත මහතා රජයේ ලලිත කලා ආයතනය හරහා දහස් ගණනක් නර්තන ගුරුවරුන් බිහි කළේය."),
        q("ශ්‍රී ලංකාවේ නර්තන ක්ෂේත්‍රයේ කාන්තා නියෝජනය ශක්තිමත් කරමින් 'ළමා මුද්‍රා නාට්‍ය' කලාව දියුණු කළ ප්‍රවීණ ශිල්පිනිය කවුද?", "වජිරා චිත්‍රසේන මහත්මිය", "රුක්මණී දේවි", "චන්ද්‍රලේඛා පෙරේරා", "මාලිනී ෆොන්සේකා", "වජිරා චිත්‍රසේන මහත්මිය මෙරට ප්‍රථම ප්‍රවීණ බැලේ හා මුද්‍රා නාට්‍ය ශිල්පිනිය ලෙස ගෞරවයට පාත්‍ර වේ."),
        q("නර්තන ව්‍යායාම හා පුහුණුවීම් මගින් පුද්ගලයෙකුගේ ශාරීරික සෞඛ්‍යයට ලැබෙන ප්‍රධානතම ප්‍රතිලාභය කුමක්ද?", "හෘද හා පෙනහළු ශක්තිය, මාංශ පේශි නම්‍යශීලී බව සහ සමබරතාව වර්ධනය වීම", "ශරීරයේ චලන හැකියාව ක්‍රමයෙන් දුර්වල වී යාම", "දණහිස් හා උකුළු සන්ධි තද වී අපහසුතා ඇති වීම", "මානසික ආතතිය හා ශාරීරික වෙහෙස පමණක් ඉහළ යාම", "නර්තනය සම්පූර්ණ ශරීරයම ක්‍රියාත්මක කරවන උසස් වායුගෝලීය හා මාංශ පේශි ව්‍යායාමයකි."),
        q("නර්තනය හැදෑරීමෙන් ශිෂ්‍යයෙකුගේ මානසික සුවතාවයට සිදුවන යහපත් බලපෑම කුමක්ද?", "මානසික ආතතිය දුරු වී සතුට, ආත්ම විශ්වාසය හා නිර්මාණශීලී බව වැඩි වීම", "ඉගෙනුම් කටයුතු අතරතුර කෝපය හා නොසන්සුන් බව වැඩි වීම", "සමාජ ඇසුරෙන් ඈත් වී තනිකම හා බිය ඇති වීම", "අවධානය බිඳ වැටී මතක ශක්තිය ක්‍රමයෙන් අඩු වීම", "රිද්මයානුකූල චලනය හා සංගීතය මොළයේ සතුට උපදවන රසායනික ක්‍රියාකාරිත්වය වර්ධනය කරයි."),
        q("සමූහ නර්තන අංගයක නියැළීමෙන් සිසුන් තුළ ගොඩනැගෙන ප්‍රධානම සමාජීය කුසලතාව කුමක්ද?", "සාමූහිකත්වය, ඉවසීම හා අන්‍යෝන්‍ය ගරුත්වය", "ආත්මාර්ථකාමී බව", "තනිවම කැපී පෙනීමට සෙසු අයට බාධා කිරීම", "නීති රීති කඩ කිරීම", "කණ්ඩායමක් ලෙස එකම තාලයට පියවර තැබීමෙන් සහයෝගීතාව හා විනය පුරුදු වේ."),
        q("නර්තනය ආරම්භ කිරීමට පෙර 'උණුසුම් කිරීමේ ව්‍යායාම' (Warm-up) කිරීම අනිවාර්ය වන්නේ ඇයි?", "මාංශ පේශි ඇදීම් හා සන්ධි ආබාධ වළක්වා ශරීරය පුහුණුවට සූදානම් කිරීමට", "විදුලි පහන් නිවෙන තුරු බලා සිටීමට", "වෙස්මුහුණු අලුත්වැඩියා කිරීමට", "ඇඳුම් මැද ගැනීමට", "හදිසි පිනුම් හා මණ්ඩි ඉරියව්වලට පෙර ශරීර උෂ්ණත්වය හා රුධිර සංසරණය වැඩි කිරීම වැදගත්ය."),
        q("නර්තන පුහුණුව අවසන් කළ වහාම සිදු කරන 'සිසිල් කිරීමේ ව්‍යායාම' (Cool-down) මගින් ලැබෙන ප්‍රයෝජනය කුමක්ද?", "හෘද ස්පන්දනය සාමාන්‍ය තත්ත්වයට ගෙන ඒම හා මාංශ පේශි වේදනාව අඩු කිරීම", "නර්තන පියවරවල වේගය තවදුරටත් වැඩි කර ගැනීම", "ප්‍රසංගයට පෙර මුහුණේ වර්ණ අංග රචනය ආලේප කිරීම", "සමස්ත නර්තන අංගය නැවත මුල සිට වේගයෙන් ඇරඹීම", "දැඩි ශාරීරික වෙහෙසකින් පසු සෙමින් හුස්ම ගැනීම හා ඇදීමේ ව්‍යායාම ශරීරය සුවපත් කරයි."),
        q("නර්තන විෂය හදාරන ශිෂ්‍යයෙකුට වර්තමානයේ විවෘත වී ඇති වෘත්තීය අවස්ථාවක් නොවන්නේ කුමක්ද?", "නීති ක්ෂේත්‍රයේ අධිකරණ විනිසුරු වෘත්තිය", "නර්තන ගුරු හා විශ්වවිද්‍යාල කථිකාචාර්ය වෘත්තිය", "වේදිකා නර්තන නිර්මාණ අධ්‍යක්ෂණය (Choreographer)", "සංස්කෘතික සංචාරක රංග ශිල්පී වෘත්තිය", "නර්තන අධ්‍යාපනය, වේදිකා නිර්මාණය, චිකිත්සාව හා සංචාරක කර්මාන්තය තුළ පුළුල් රැකියා අවස්ථා පවතී."),
        q("මානසික හා ශාරීරික රෝගීන් සුවපත් කිරීම සඳහා නර්තනය යොදාගන්නා නූතන වෘත්තීය ක්ෂේත්‍රය කුමක්ද?", "නර්තන හා චලන චිකිත්සාව (Dance Movement Therapy)", "සම්භාව්‍ය පුස්කොළ පොත් පිටපත් ලේඛන කලාව", "වේදිකා ආලෝක පද්ධති කාර්මික සැලසුම්කරණය", "ප්‍රාදේශීය ඉතිහාස සෙල්ලිපි සංරක්ෂණ කලාව", "චලනය හා රිද්මය ඇසුරෙන් මානසික ආතතිය හා චලන අපහසුතා සමනය කිරීමට නර්තන චිකිත්සාව යොදයි."),
        q("නර්තන ක්ෂේත්‍රයේ 'නර්තන නිර්මාණ ශිල්පියෙකු' (Choreographer) විසින් ඉටු කරන ප්‍රධාන කාර්යභාරය කුමක්ද?", "තේමාවකට අනුව නැටුම් පියවර, අවකාශ රටා සහ ප්‍රසංග ආකෘතිය සැලසුම් කිරීම", "රංග ශාලාවේ දොරටු අසල සිට ප්‍රේක්ෂක අසුන් අංක පරීක්ෂා කිරීම", "ප්‍රසංග ශාලාවේ ප්‍රේක්ෂක අසුන් පෙළින් පෙළට පිළිවෙළකට සකස් කිරීම", "රංග වස්ත්‍ර හා උඩරට හඟල රෙදි මැසීමේ කටයුතු පමණක් සිදු කිරීම", "කොරියෝග්‍රැෆර් හෙවත් නර්තන නිර්මාණකරු මුළු ප්‍රසංගයේම කලාත්මක දැක්ම මෙහෙයවයි."),
        q("ප්‍රසංග වේදිකාවකදී නර්තන ශිල්පියෙකු සතු විය යුතු උසස්ම වෘත්තීය ආචාර ධර්මය කුමක්ද?", "වේලාවට වැඩ කිරීම, ගුරුවරුන්ට හා සගයන්ට ගරු කිරීම සහ රංග භූමිය පිරිසිදුව තැබීම", "වේදිකාව පිටුපස ආහාර ගනිමින් පෙරහුරු කාලය මඟ හැරීම", "ප්‍රේක්ෂකයන්ගේ විවේචන හමුවේ වේදිකාව මැදදී කෝප වීම", "සගයන්ගේ රංග වස්ත්‍ර හා උපාංග අපිළිවෙළට දමා යාම", "කලාත්මක දක්ෂතාව මෙන්ම විනය හා වෘත්තීය ආචාර ධර්ම කලාකරුවාගේ ගෞරවය රකී."),
        q("සම්ප්‍රදායික නර්තන ඇඳුම් හා වාද්‍ය භාණ්ඩ භාවිතයෙන් පසු නැවත තැන්පත් කිරීමේදී අනුගමනය කළ යුතු නිවැරදි පිළිවෙත කුමක්ද?", "පිරිසිදු කර, වියළා ගෞරවාන්විතව ආරක්ෂිත පෙට්ටිවල ඇසිරීම", "බිම අතහැර දමා යාම", "තෙත පිටින් ප්ලාස්ටික් මළුවල බැඳීම", "වැස්සේ තැබීම", "පූජනීය භාණ්ඩ ලෙස සලකා නැටුම් ආභරණ හා බෙර රැකබලා ගැනීම පරම්පරාගත ශිල්පීය සිරිතකි."),
        q("නර්තන ප්‍රසංගයකදී 'පසුබිම් රංග පසුතල' (Stage Backdrop) සැලසුම් කිරීමේ මූලික අරමුණ කුමක්ද?", "රංගනයේ තේමාවට උචිත පරිසරය ප්‍රේක්ෂකයාට සමීප කිරීම", "ශිල්පීන් ප්‍රේක්ෂකයාගෙන් සම්පූර්ණයෙන් වැසීම", "වේදිකාව කුඩා කිරීම", "ශබ්දය අඩු කිරීම", "විශාල පසුතල මගින් නැටුම් ශිල්පියාගේ රංගනය නොවැසෙන පරිදි තේමාව ඉස්මතු කළ යුතුය."),
        q("වේදිකා නර්තනයකදී 'උච්චතම අවස්ථාව' (Climax) ලෙස සැලකෙන්නේ කුමන කොටසද?", "රංගනයේ භාවමය හා රිද්මයානුකූල උද්වේගය ඉහළම තලයට පත්වන අවස්ථාව", "වේදිකා තිරය ඇරෙන පළමු තත්පරය", "ශිල්පීන් වේදිකාවෙන් බැස ගිය පසු කාලය", "නිවේදකයා කතා කරන වේලාව", "සාර්ථක නර්තන නිර්මාණයක ආරම්භය, විකාශනය, උච්චතම අවස්ථාව හා අවසානය මැනවින් ගැළපේ."),
        q("තාලමක 'විභාග' හෙවත් කොටස් වෙන් කිරීම නර්තන ශිල්පියාට ප්‍රයෝජනවත් වන්නේ කෙසේද?", "දීර්ඝ තාල ආවර්තන පහසුවෙන් ගණන් කර මතක තබා ගැනීමට", "තාලම්පට කැඩීමෙන් වළක්වා ගැනීමට", "ගීතයේ පද අමතක කිරීමට", "වේදිකාව මැනීමට", "මාත්‍රා 12 හෝ 16 වැනි දිගු තාල කුඩා කොටස්වලට බෙදා ගැනීමෙන් නැටීම පහසු වේ."),
        q("උඩරට නර්තනයේ සරඹ පුහුණු වන විට ගුරුවරයා 'තකුඳ තකුඳ තකුඳ තා' යනුවෙන් දෙන රිද්මය අයත් වන්නේ කුමන තාල ගණයටද?", "චතුරස්‍ර හෙවත් සිව් මාත්‍රා ගණයට", "තිස්‍ර හෙවත් තුන් මාත්‍රා ගණයට", "ඛණ්ඩ හෙවත් පස් මාත්‍රා ගණයට", "සංකීර්ණ නව මාත්‍රා ගණයට", "ත කුං ද යන අක්ෂර හතර අනුව සිව් මාත්‍රා ඒකක සරඹ මූලික පුහුණුවේ යෙදේ."),
        q("දේශීය නර්තනයේ 'තිස්‍ර ගතිය' යන්නෙන් අදහස් කෙරෙන මාත්‍රා බෙදීම කුමක්ද?", "මාත්‍රා 3 බැගින් වූ රිද්ම චලනය", "මාත්‍රා 4 බැගින් වූ රිද්ම චලනය", "මාත්‍රා 7 බැගින් වූ රිද්ම චලනය", "මාත්‍රා 9 බැගින් වූ රිද්ම චලනය", "තකිට තකිට (1-2-3) යන ගණනය කිරීම අනුව මාත්‍රා තුනේ ලාලිත්‍යමය ගමන තිස්‍ර ගතියයි."),
        q("නර්තන නිර්මාණයකදී 'සමමිතික රටාවක්' (Symmetrical design) වේදිකාවේ ගොඩනැගෙන්නේ කෙසේද?", "වේදිකාවේ මධ්‍ය රේඛාව දෙපස ශිල්පීන් සමාන ඉරියව් හා දුරකින් ස්ථානගත වීමෙන්", "එක් පැත්තක පමණක් සියලු ශිල්පීන් රැස්වීමෙන්", "සෑම ශිල්පියෙකුම වෙනස් නැටුමක් නැටීමෙන්", "වේදිකා ආලෝකය නිවා දැමීමෙන්", "සමමිතික සැකසුම නර්තනයට තැන්පත් බව, ගෞරවය හා ස්ථාවරත්වය එක් කරයි."),
        q("වේදිකාව මත 'අසමමිතික රටාවක්' (Asymmetrical design) යොදාගැනීමට නිර්මාණකරුවෙකු පෙළඹෙන්නේ කුමන අවස්ථාවකද?", "නාටකීය ගැටුම, විවිධත්වය හෝ චලන ගතිකත්වය වැඩි කිරීමට", "ශිල්පීන්ට ඉඩ මදි වූ විට පමණක්", "නැටුම නැවැත්වීමට", "තාලය වැරදුණු විට", "අසමමිතික හැඩතල නූතන නර්තන නිර්මාණවල කුතුහලය හා ශක්තිය ජනිත කිරීමට යොදයි."),
        q("නර්තන ප්‍රසංගයක සමස්ත කාලසටහන හා කාර්මික අංග සම්බන්ධීකරණය කරන ප්‍රධාන පුද්ගලයා කවුද?", "වේදිකා කළමනාකරු (Stage Manager)", "වෙස්මුහුණු කැටයම්කරු", "ප්‍රේක්ෂක නියෝජිතයා", "වැඩසටහන් චිත්‍ර ශිල්පියා", "තිරය, ආලෝකය, ශබ්දය සහ ශිල්පීන්ගේ වේදිකා පිවිසුම නියමිත තත්පරයට කළමනාකරණය වේ."),
        q("නර්තන ශිල්පියෙකුගේ 'දරා ගැනීමේ ශක්තිය' (Stamina) වැඩි දියුණු කර ගැනීමට වඩාත්ම උපකාරී වන පුහුණුව කුමක්ද?", "දිනපතා නොකඩවා ලය වැඩි කරමින් කරන සරඹ හා වායුගෝලීය ව්‍යායාම", "සතියකට වරක් කෙටි වේලාවක් ඉඳගෙන සිටීම", "ගීතවලට සවන් දීම පමණක්", "අධික මේද ආහාර ගැනීම", "පහළ මණ්ඩි ඉරියව්වේ රැඳෙමින් නොනවත්වා නැටීමට ඉහළ ශාරීරික දරාගැනීමක් අවශ්‍ය වේ."),
        q("ශ්‍රී ලංකාවේ ජාතික උත්සව හා සංස්කෘතික සංචාරක ප්‍රවර්ධනය සඳහා දේශීය නර්තනය දායක වන්නේ කෙසේද?", "රටේ අනන්‍ය සංස්කෘතික උරුමය ලොවට පෙන්වා විදේශ විනිමය හා ගෞරවය ගෙන ඒමෙන්", "විදේශීය නැටුම් පමණක් අනුකරණය කිරීමෙන්", "පැරණි බෙර භාවිතය අත්හැරීමෙන්", "සාම්ප්‍රදායික කලාකරුවන් නොසලකා හැරීමෙන්", "උඩරට, පහතරට හා සබරගමු නැටුම් ශ්‍රී ලංකාවේ සංස්කෘතික අනන්‍යතාවයේ ප්‍රධාන තානාපතිවරයෙකි."),
        q("නර්තනය හා සෙසු කලාවන් අතර පවතින අන්තර් සබැඳියාව පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?", "නර්තනය යනු සංගීතය, සාහිත්‍යය, චිත්‍ර හා නාට්‍ය යන සියලු කලාවන්හි සුසංයෝගයකි", "නර්තනය සඳහා සංගීතය, කාව්‍ය සාහිත්‍යය හෝ තාල වාද්‍ය භාණ්ඩ කිසිවක් අවශ්‍ය නොවේ", "නර්තනය චිත්‍ර කලාව, කැටයම් හා වර්ණ සංයෝජනය සමඟ සම්බන්ධ නොවන හුදු චලනයකි", "නර්තනය යනු භාව ප්‍රකාශනයෙන් තොර හුදු ශාරීරික ව්‍යායාම පමණක් සිදු කරන ක්‍රීඩාවකි", "කවි ගායනා, වෙස්මුහුණු කැටයම්, වර්ණ රංග වස්ත්‍ර හා තාල වාදන සියල්ල නැටුමේදී එක් වේ."),
        q("ශ්‍රී ලාංකේය පාසල් පද්ධතිය තුළ නර්තනය ප්‍රායෝගික හා න්‍යායාත්මක විෂයයක් ලෙස ඉගැන්වීමේ ප්‍රධාන අරමුණ කුමක්ද?", "සංස්කෘතික උරුමය රැකගත් සංවේදී, නිර්මාණශීලී හා සමබර පුරවැසියෙකු බිහි කිරීම", "සිසුන්ට අනෙක් පාසල් විෂයයන් සම්පූර්ණයෙන් අමතක කරවීම", "පාසල් අධ්‍යයන කාලය හා විභාග කටයුතු අඩු කර ගැනීම", "වෙස් ඇඳුම් හා වාද්‍ය භාණ්ඩ අලෙවිය පමණක් වැඩි කිරීම", "අධ්‍යාපනික නර්තනය මගින් සිසුවාගේ ශරීරය, මනස, භාවය හා සමාජ ආකල්ප සමබරව සංවර්ධනය වේ."),
        q("වේදිකා නර්තනයකදී සාම්ප්‍රදායික පන්දම් එළිය වෙනුවට නූතන විදුලි ආලෝකය යෙදීමේදී පවත්වා ගත යුතු සෞන්දර්ය ගුණය කුමක්ද?", "සාම්ප්‍රදායික ගුප්ත හා උණුසුම් රංග පරිසරයට හානි නොවන සේ ආලෝකය හැසිරවීම", "වේදිකාව පුරාම ඉතා දැඩි සුදු පැහැති ආලෝකය පමණක් නොවෙනස්ව දැල්වීම", "මුළු රංගනය අතරතුරම වේදිකාව සම්පූර්ණ අඳුරේ තබා චලන සැඟවීම", "චලන හා භාව නොසලකා අධික වර්ණවත් විදුලි එළි පමණක් වේගයෙන් මාරු කිරීම", "රංගනයේ භාවමය ගැඹුර රැකෙන පරිදි ආලෝක තීව්‍රතාව හා වර්ණ සංයෝජනය කළ යුතුය."),
        q("නව නර්තන නිර්මාණයක් සිදු කිරීමේදී 'ගවේෂණය' හා 'පෙරහුරු' (Rehearsals) ඉතා වැදගත් වන්නේ ඇයි?", "පියවරවල නිරවද්‍යතාව, කණ්ඩායම් සම්බන්ධීකරණය හා කාල කළමනාකරණය තහවුරු කිරීමට", "නැටුම් ශිල්පීන් ප්‍රසංගයට පෙර අධික ලෙස වෙහෙසට හා පීඩාවට පත් කිරීමට", "වෙස් ඇඳුම් හා රංග ආභරණ ප්‍රසංගයට පෙර ඉක්මනින් පරණ කර දැමීමට", "රංග වේදිකාවේ ලෑලි බිම සූරා දමා පාද සලකුණු ඉතිරි කර තැබීමට", "ප්‍රමාණවත් පෙරහුරු නොමැති වුවහොත් ප්‍රසංගයේදී තාල වැරදීම් හා ගැටීම් සිදුවිය හැක."),
        q("සිංහල ජන කවියක් හෝ ගොයම් කවියක් ඇසුරෙන් නව නර්තනයක් නිර්මාණය කිරීමේදී පළමුව අධ්‍යයනය කළ යුත්තේ කුමක්ද?", "කවියේ තාල රිද්මය, පසුබිම් ජීවන රටාව හා හැඟීම් පරාසය", "විදේශීය පොප් සංගීත රටා", "යාන්ත්‍රික රොබෝ චලන", "වෙස්මුහුණු කැපීමේ ක්‍රම", "ගැමි ජීවිතයේ සැබෑ අත්දැකීම් හා කවියේ නාද මාලාව නිවැරදිව ග්‍රහණය කර ගැනීමෙන් ජීවමාන නැටුමක් මැවේ."),
        q("නර්තන විද්‍යාවේදී 'ගති' යන වචනයෙන් සාමාන්‍යයෙන් හැඳින්වෙන්නේ කුමක්ද?", "නර්තනයේදී ගමන් කරන ආකාරය සහ සත්ව හෝ මිනිස් ගමන් අනුකරණය", "ගැටබෙරයේ වම් ඇසින් උපදින ගැඹුරු බෙර හඬ", "උඩරට වෙස් ඇඳුමේ පසුපස එල්ලෙන රෙදි වර්ණය", "ප්‍රසංග වේදිකාවේ ඉදිරිපස තිරයේ සම්මත පළල", "සිංහ ගති, මයුර ගති, ගජ ගති හා හංස ගති ආදී ගමන් විලාස ශාස්ත්‍රීය නර්තනයේ වැදගත් වේ."),
        q("දේශීය නර්තන වේදිකාවේ ශිල්පියා පොළොවට අඩිය ගසන ආකාරය අනුව තාල බර තැබීමේ වෙනසක් සිදු කළ හැක්කේ කෙසේද?", "විළුඹ, ඇඟිලි තුඩු හෝ සම්පූර්ණ පතුල විවිධ ලයට අනුව තැබීමෙන්", "කකුල් දෙකම එකට බැඳ ගැනීමෙන්", "සපත්තු ගලවා ඉවත් කිරීමෙන් පමණක්", "බිම වාඩි වී සිටීමෙන්", "පාද තැබීමේ සියුම් වෙනස්කම් මගින් රිද්මයේ තියුණු බව හෝ මෘදු බව පාලනය කළ හැක."),
        q("නර්තනය සහ 'ශ්‍රව්‍ය දෘශ්‍ය මාධ්‍යය' එක්වීමෙන් වර්තමානයේ නර්තන කලාවට සිදු වී ඇති ප්‍රධාන සේවාව කුමක්ද?", "දේශීය නර්තනය සංරක්ෂණය වීම හා ගෝලීය ප්‍රේක්ෂකයා වෙත කඩිනමින් ළඟා වීම", "සාම්ප්‍රදායික උඩරට හා පහතරට බෙර සම්පූර්ණයෙන්ම අභාවයට යාම", "රට පුරා පවතින සාම්ප්‍රදායික කලායතන හා නැටුම් පාසල් වැසී යාම", "නර්තන රංගනයේදී හස්ත මුද්‍රා හා අභිනය භාවිතය සම්පූර්ණයෙන් නතර වීම", "වීඩියෝ පටිගත කිරීම් හා ඩිජිටල් සංරක්ෂණය මගින් අනාගත පරපුරට සම්ප්‍රදාය රැකගත හැකි වේ."),
        q("වෘත්තීය නර්තන කණ්ඩායමක් විදේශ සංචාරයකදී ඉදිරිපත් කරන 'සංස්කෘතික ප්‍රසංගයක්' සතු විය යුතු මූලික ගුණාංගය කුමක්ද?", "කාල කළමනාකරණය, උසස් ප්‍රමිතිය, විවිධත්වය හා අනන්‍ය සංස්කෘතික වටිනාකම", "හැකිතාක් ප්‍රමාද වී ආරම්භ කිරීම", "එකම පියවර පැයක් පුරා නැවත නැවත කිරීම", "අපිරිසිදු රංග වස්ත්‍ර ඇඳීම", "විධිමත්ව සැලසුම් කළ කෙටි හා විචිත්‍ර අංග පෙළක් විදේශීය ප්‍රේක්ෂකයා ආකර්ෂණය කරයි."),
        q("උඩරට නර්තන ප්‍රසංගයකදී 'මඟුල් බෙර' වාදනයෙන් පසුව ඉදිරිපත් කිරීමට වඩාත්ම උචිත ආරම්භක නර්තන අංගය කුමක්ද?", "පූජා නර්තනයක් හෝ නමස්කාර නැටුමක්", "හොරොව්ව ගැලවීමේ නැටුමක්", "සොකරි හාස්‍ය අංගයක්", "කෝලම් හේවා නැටුමක්", "මඟුල් බෙරයෙන් ඇති කරන ගෞරවනීය හා ශුභ පරිසරය පූජා නැටුමකින් ඉදිරියට ගෙන යයි."),
        q("වේදිකාවක 'දිශානතිය' හඳුනා ගැනීමේදී ප්‍රේක්ෂකයාට මුහුණලා ඉදිරිපසින්ම පිහිටි කලාපය හඳුන්වන්නේ කෙසේද?", "ඉදිරි වේදිකාව (Downstage)", "පසු වේදිකාව (Upstage)", "වේදිකාවෙන් පිටත (Offstage)", "ප්‍රේක්ෂකාගාරය (Auditorium)", "පැරණි ඇලවුණු වේදිකා සැලැස්ම අනුව ප්‍රේක්ෂකයාට ආසන්න කොටස Downstage ලෙසත් පසුපස කොටස Upstage ලෙසත් නම් කෙරේ."),
        q("නර්තන නිර්මාණයේදී 'ප්‍රතිරූපණ' (Mirroring) ක්‍රමය යොදා ගැනීමෙන් වේදිකාව මත ඇති කරන්නේ කුමන ආකාරයේ රසයක්ද?", "දෙදෙනෙකු හෝ කණ්ඩායම් දෙකක් අතර පවතින ඒකාබද්ධතාව හා ප්‍රතිබිම්බමය සුන්දරත්වය", "ප්‍රේක්ෂකයා නොමඟ යවා කතා පුවත සම්පූර්ණයෙන් අවුල් කිරීම", "බෙර වාදකයාගේ තාලය බිඳ දමා අසමමිතික ශබ්දයක් ඇති කිරීම", "රංගනය අතරතුර බෙර වාදනයට බාධා කරමින් වේදිකාව හිස් කිරීම", "වම් හා දකුණු පස ශිල්පීන් ප්‍රතිවිරුද්ධ දිශාවට සමාන ඉරියව් දැක්වීමෙන් දර්ශනීය රටාවක් මැවේ."),
        q("සම්ප්‍රදායික නර්තන ශිල්පියෙකු තම හැකියාවන් වැඩි දියුණු කර ගැනීමට නිතර පුරුදු විය යුතු 'සමතුලිතතා අභ්‍යාසයක්' කුමක්ද?", "මණ්ඩි ඉරියව්වේ සහ ඒකපාද ඉරියව්වේ ස්ථාවරව රැඳී සිටීමේ අභ්‍යාස", "පුටුවක වාඩි වී හස්ත මුද්‍රා පමණක් ඉදිරිපත් කිරීමේ අභ්‍යාස", "බිත්තියකට හේත්තු වී කවි ගායනා කිරීමේ අභ්‍යාස පමණක්", "දෑස් වසාගෙන වේදිකාව පුරා වේගයෙන් දිවීමේ අභ්‍යාස", "ශරීරයේ ගුරුත්ව කේන්ද්‍රය මැදි කොට ස්ථාවරව රැඳීම නැටුමේ උසස් තාක්ෂණයකි."),
        q("පහතරට සහ උඩරට නැටුම් එක්කර සාදන 'ත්‍රිවිධ සම්ප්‍රදාය සම්මිශ්‍රණ' නර්තන අංගයක සාර්ථකත්වය රඳා පවතින්නේ කුමක් මතද?", "එක් එක් සම්ප්‍රදායේ ආවේණික බෙර හඬ, තාල සහ පියවර සුසංයෝග කිරීම මත", "සියලුම ඇඳුම් එක පුද්ගලයෙකුට ඇන්දවීම මත", "සබරගමු නැටුම ඉවත් කිරීම මත", "නිහඬව රඟ දැක්වීම මත", "සම්ප්‍රදායන් තුනේම රිද්ම රටා ගැළපෙන සේ පාලම් තනමින් ඉදිරිපත් කිරීම ප්‍රේක්ෂක ආකර්ෂණය දිනා ගනී."),
        q("දේශීය නර්තන විභාග හා තරගාවලිවලදී 'අංග ලක්ෂණ' හා 'තාල අවබෝධය' පරීක්ෂා කිරීමේ මූලික අරමුණ කුමක්ද?", "නිවැරදි සම්ප්‍රදායික ශිල්පීය පදනම රැක ගැනීම සහ ගුණාත්මක බව මැනීම", "තරගකරුවන් අතර අනවශ්‍ය මතභේද හා තරහව ඇති කිරීම", "නව නිර්මාණශීලී ජන නැටුම් පාසල්වලින් තහනම් කිරීම", "සම්ප්‍රදායික බෙර වාද්‍ය භාණ්ඩ භාවිතය ක්‍රමයෙන් අඩු කිරීම", "සම්මත නිර්ණායක යටතේ ඇගයීම මගින් ශාස්ත්‍රීය ප්‍රමිතිය අනාගතයට සුරැකේ."),
        q("නර්තන විද්‍යාගාරයක හෝ කලායතනයක 'පහන් පැල' ඉදිරිපිට සුදු රෙද්දක් එළා පවත්වන 'පාද නමස්කාර' චාරිත්‍රය හෙවත් පා පිටුව පුහුණුව අරඹන්නේ ඇයි?", "ශිල්පය ඉගෙනීමට ආරම්භයේදී භක්තිය, විනය හා ගුරු ගෞරවය තහවුරු කිරීමට", "පුහුණුව සඳහා එළූ සුදු රෙදි පසුව සේදීම පහසු කර ගැනීමට", "නැටුම් ශාලාවේ පරණ ලී බිම අලුත්වැඩියා කර සකසා ගැනීමට", "පංතියට පැමිණි ප්‍රේක්ෂකයන් ගණන නිවැරදිව ගණන් කර ගැනීමට", "දඬියම් කඳ අල්ලා මූලික පාද හුරුව ඇරඹීම සිංහල කලායතන සම්ප්‍රදායේ උතුම් චාරිත්‍රයකි."),
        q("තාලමක මුළු මාත්‍රා 8 ක් ඇති විට එය 'ද්‍රුත ලයෙන්' නැටීමේදී සිදුවන්නේ කුමක්ද?", "මාත්‍රා 8 ඉතා වේගවත් කාල පරතරයකින් නැටීම", "මාත්‍රා 8 වෙනුවට මාත්‍රා 20 ක් ගැනීම", "නැටුම නතර කර ඉඳගැනීම", "විලම්බ ලයට වඩා සෙමින් නැටීම", "ද්‍රුත ලයේදී මාත්‍රා ගණන නොවෙනස්ව පවතින අතර මාත්‍රාවෙන් මාත්‍රාවට ගතවන කාලය කෙටි වේ."),
        q("වන්නමක හෝ ගමන් පදයක මධ්‍ය ලයේ සිට එකවර ද්‍රුත ලයට මාරු වන විට නර්තන ශිල්පියාගේ ශරීර චලනවල සිදුවන වෙනස කුමක්ද?", "පියවර හා අත් මාරු තුන් හතර ගුණයක ජවයකින් හා වේගයකින් ක්‍රියාත්මක වීම", "නර්තනයේ සියලුම අත් හා පාද චලන එක්වරම නතර වීම", "වේදිකාවේ මැද බිම වැතිරී හාන්සි වී රඟ දැක්වීම", "තාලය අත්හැර වේදිකාවෙන් පසුපසට ඇවිදගෙන යාම", "බෙර වාදනයේ 'පෙරළුම' හා කස්තිරම සමඟ නැට්ටුවාගේ වේගය ඉහළ නැංවීම නර්තනය උද්වේගකර කරයි."),
        q("නර්තන කලාවට 'ප්‍රේක්ෂක ප්‍රතිචාරය' (Audience Response) වැදගත් වන්නේ කුමන ආකාරයෙන්ද?", "ශිල්පියාගේ රස නිෂ්පත්තිය සාර්ථකදැයි හඳුනා ගැනීමට හා ධෛර්යයක් ලබා ගැනීමට", "ප්‍රසංග ශාලාවේ වේදිකා සැරසිලි මිල ගණන් වැඩි කිරීමට", "නැටුම අතරතුර බෙරයේ හම් සම මාරු කර ගැනීමට", "රංග පීඨයේ විදුලි ආලෝක පද්ධතිය සම්පූර්ණයෙන් නිවීමට", "ප්‍රේක්ෂකයා තුළ රසය උපදවා ගැනීම නර්තනයේ අවසාන ඉලක්කය බැවින් ඔවුන්ගේ ප්‍රතිචාරය ඉතා වටී."),
        q("සම්ප්‍රදායික ගැමි ජන නැටුමක් වූ 'කුළු නැටුම' නව වේදිකා අංගයක් ලෙස සැකසීමේදී එක් කළ හැකි හොඳම උපාංගය කුමක්ද?", "වී පොළන ගැමි කාන්තාවන්ගේ රිද්මයානුකූල චලන හා ජන ගායනා", "රොබෝ නැටුම් හඬ පට", "බටහිර වයලීන් සෝනාටා", "සන්නි වෙස්මුහුණු", "ජන ජීවිතයේ කෘෂිකාර්මික කාර්යයන්හි සැබෑ රිද්මය රැකගෙන රංගනය සකස් කිරීම සාර්ථක වේ."),
        q("සිංහල අවුරුදු උත්සවයක හෝ සංස්කෘතික සංදර්ශනයකදී 'රබන් නැටුම' ඉදිරිපත් කිරීමෙන් නිරූපණය වන සමාජ අගය කුමක්ද?", "ගැමි ප්‍රීතිය, සහෝදරත්වය සහ කණ්ඩායම් සමගිය", "ශෝකී වැළපීම, විරහව සහ පරාජිත මානසිකත්වය", "යුද ගැටුම්, රෞද්‍ර කෝපය සහ සතුරු ආක්‍රමණ", "සමාජයෙන් වෙන්වීම, හුදකලා බව සහ නිහඬ භාවනාව", "අත් රබන් හා බැංකු රබන් වටා එක්වී නැටීමෙන් ජන සමාජයේ සාමූහික සතුට ප්‍රකාශ වේ."),
        q("ශ්‍රී ලාංකේය නර්තන වංශකතාවේ 'සබරගමු නර්තන සම්ප්‍රදාය' සඳහා සුවිශේෂී ශාස්ත්‍රීය සේවාවක් ඉටු කළ ආචාර්යවරයෙකු වන්නේ කවුද?", "සිරිසේන ගමගේ හා පී.කේ. වැලිපත ගුරුන්නාන්සේ", "මාර්ටින් වික්‍රමසිංහ හා ජී.බී. සේනානායක", "ආනන්ද සමරකෝන් හා සුනිල් ශාන්ත මහතා", "මහාචාර්ය සෙනරත් පරණවිතාන මහතා", "රත්නපුර හා සබරගමු කලායතන පරම්පරා මෙම දුර්ලභ නර්තන සම්ප්‍රදාය අදටත් රැකගෙන ඇත."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'මාතර, රයිගම් සහ බෙන්තර' යන ප්‍රාදේශීය ගුරුකුල බෙදීමෙන් සිදුව ඇති කලාත්මක ප්‍රතිලාභය කුමක්ද?", "එකම සම්ප්‍රදාය තුළ විවිධ ශෛලීන් හා පද රටා පොහොසත් වීම", "පහතරට නැටුම විනාශ වීම", "යක්බෙරය භාවිතයෙන් ඉවත් වීම", "තෙල්මේ නැටුම අමතක වීම", "ප්‍රාදේශීය ශිල්පීය විවිධත්වය නිසා පහතරට නැටුමේ පද, කවි හා වෙස්මුහුණු කලාව ඉතා පොහොසත් විය."),
        q("නර්තන විද්‍යාවේදී 'තාල අවබෝධය' වැඩි දියුණු කර ගැනීමට ශිෂ්‍යයෙකුට කළ හැකි හොඳම දෛනික අභ්‍යාසය කුමක්ද?", "අතින් තාල තබමින් බෙර පද සහ තාල ගායනය (පද කීම) පුහුණු වීම", "සංගීතය වසා දමා නිදා ගැනීම", "පින්තූර ඇඳීම පමණක්", "නැටුම් පොත් රැස් කිරීම පමණක්", "අතින් තිත තබා පද කියමින් පාද තැබීම සම්ප්‍රදායිකව තාල ඥානය තහවුරු කරන හොඳම ක්‍රමයයි."),
        q("සම්ප්‍රදායික බෙර පදයක් මුඛයෙන් උච්චාරණය කිරීමේදී අවධාරණය කෙරෙන නිවැරදි ක්‍රමය කුමක්ද?", "සෑම අක්ෂරයකම මාත්‍රා කාලය හා බර තැබීම නිවැරදිව ප්‍රකාශ කිරීම", "හැකිතාක් ඉක්මනින් අපැහැදිලිව කීම", "වචන කිහිපයක් මඟ හැරීම", "හුස්ම නොගෙන අවසන් කිරීම", "පැහැදිලි හා රිද්මයානුකූල අක්ෂර උච්චාරණය මඟින් නැට්ටුවාගේ මනසෙහි රිද්මය තහවුරු වේ."),
        q("දේශීය නර්තනයේ 'ගමන් මාත්‍රාව' පුහුණු වීමෙන් වේදිකාව මත නර්තන ශිල්පියාට ලැබෙන හැකියාව කුමක්ද?", "එක් ස්ථානයක සිට තවත් ස්ථානයකට රිද්මය නොබිඳී අලංකාරව ගමන් කිරීම", "තාලය අමතක වී වේදිකාවෙන් පහළට ඇද වැටීම", "අනෙක් සගයන්ගේ චලන රටාවට බාධා වන සේ හැපීම", "බෙර වාදනය සම්පූර්ණයෙන් නවත්වා සාමාන්‍යයෙන් ඇවිදීම", "සියලු ගමන් පියවර තාලයට අනුගත වීමෙන් වේදිකා රංගනය අඛණ්ඩ කලා කෘතියක් බවට පත්වේ."),
        q("නව නිර්මාණාත්මක මුද්‍රා නාට්‍යයකදී 'සංකේතවාදය' (Symbolism) යොදාගන්නා ආකාරයට උදාහරණයක් කුමක්ද?", "රතු රෙදි පටියක් මගින් ගින්න හෝ යුද්ධය නිරූපණය කිරීම", "සැබෑ ගිනි ගොඩක් වේදිකාවේ දැල්වීම", "කතාව කියවා පෙන්වීම", "වේදිකාව හිස්ව තැබීම", "නාටකීය උපාංග, වර්ණ හා මුද්‍රා මඟින් ගැඹුරු අර්ථ සංකේතවත් කිරීම නූතන නර්තනයේ සුන්දර ලක්ෂණයකි."),
        q("ප්‍රසංගයකදී නැටුම් කණ්ඩායමක ඇඳුම් පැළඳුම් සියල්ල එකම ප්‍රමිතියකින් හා පිරිසිදුව පවත්වා ගැනීම වැදගත් වන්නේ ඇයි?", "කණ්ඩායමේ ඒකාග්‍රතාව, වෘත්තීයභාවය හා ප්‍රේක්ෂක ආකර්ෂණය ඉහළ නැංවීමට", "ඇඳුම්වල බර වැඩි කිරීමට", "ශිල්පීන් හඳුනා ගැනීම අපහසු කිරීමට", "කාලය නාස්ති කිරීමට", "විවිධ ශිල්පීන්ගේ ඇඳුම් වර්ණ හා පැළඳුම් අනුකූල වීමෙන් සමස්ත වේදිකා දර්ශනය ඔප් නැංවේ."),
        q("වයස අවුරුදු 15–16 (O/L) සිසුන් නර්තනය හැදෑරීමේදී ඔවුන්ගේ නිර්මාණාත්මක කුසලතා මැනීම සඳහා පාසල් මට්ටමින් වඩාත් උචිත ඇගයීම් ක්‍රමය කුමක්ද?", "සම්ප්‍රදායික පද හා නව සමූහ නිර්මාණ ප්‍රායෝගිකව ඉදිරිපත් කරවීම", "නර්තන පොත් කටපාඩම් කරවීම පමණක්", "නිහඬව අසුන් ගෙන සිටීම", "චිත්‍ර පමණක් ඇඳීම", "න්‍යායාත්මක දැනුම හා ප්‍රායෝගික නිර්මාණශීලීත්වය යන දෙකම සමතුලිතව මැන බැලීම අධ්‍යාපනික අරමුණයි."),
        q("නර්තනය සහ සංගීතය යන විෂයයන් දෙකෙහිම 'ලය' පිළිබඳ දැනුම තිබීම නර්තන ශිල්පියෙකුට අත්‍යවශ්‍ය වන්නේ ඇයි?", "ගායනයට, වාදනයට හා පාද චලනවලට අතර විසංවාදයක් ඇති නොවීමට", "වාද්‍ය භාණ්ඩ අලුත්වැඩියා කිරීමට", "ශබ්ද පරිපාලකයා වීමට", "ඇඳුම් මැසීමට", "සංගීත ලය වෙනස් වන සෑම මොහොතකම නැට්ටුවාද එයට සමානුපාතිකව ප්‍රතිචාර දැක්විය යුතුය."),
        q("නර්තන ක්ෂේත්‍රයේ නියැළෙන තරුණ ශිල්පියෙකු තම කලා කෞශල්‍යය ආරක්ෂා කර ගැනීමට නිරන්තරයෙන් කළ යුත්තේ කුමක්ද?", "අඛණ්ඩ ප්‍රායෝගික පුහුණුව හා ගුරු උපදෙස් ලැබීම", "පැරණි බෙර පද අමතක කර හැරීම", "විවේචන හේතුවෙන් වේදිකාවෙන් ඈත් වීම", "ශාරීරික ව්‍යායාම සම්පූර්ණයෙන් නැවැත්වීම", "කලාත්මක කුසලතාව නිරන්තර අභ්‍යාසයෙන් හා විනයානුකූල ජීවිතයෙන් පෝෂණය වේ."),
        q("නර්තන ප්‍රසංගයකදී 'ප්‍රස්ථාවනාව' (Prologue) මඟින් ප්‍රේක්ෂකයාට සැපයෙන මූලික පහසුව කුමක්ද?", "ඉදිරිපත් කරන නැටුමේ තේමාව හා පසුබිම වටහා ගැනීම", "වේදිකාවේ මිල ගණන් පිළිබඳ දැන ගැනීම", "බෙර වාදකයාගේ නම අනුමාන කිරීම", "විදුලි පහන් සවි කරන ආකාරය ඉගෙනීම", "කෙටි හඳුන්වාදීමක් මඟින් ප්‍රේක්ෂකයා රංගනයේ අර්ථය වෙත මනසින් සූදානම් කරයි."),
        q("සම්ප්‍රදායික ගැමි නැටුමක් වන 'සවරං නැටුම' ඉදිරිපත් කිරීමේදී නර්තන ශිල්පීන් අත දරන විශේෂ උපාංගය කුමක්ද?", "අලංකාර වල් විදුනාවක් හෙවත් චාමරය", "ලෝහමය තාලම්පට යුගලය", "මැටි කළගෙඩිය", "කිරි කළ හා පන්දම", "චාමර හෙවත් සවරං කරකවමින් තාලයට පාද තැබීම සවරං නැටුමේ සුන්දර ලක්ෂණයකි."),
        q("දේශීය නර්තන තාල ක්‍රමයේදී 'මැදුම් සුළු තනම' තාලයේ මාත්‍රා 7 බෙදී යන සාමාන්‍ය රටාව කුමක්ද?", "මාත්‍රා 3 + 4 ලෙස", "මාත්‍රා 5 + 5 ලෙස", "මාත්‍රා 4 + 4 ලෙස", "මාත්‍රා 2 + 2 ලෙස", "දේශීය තාල විග්‍රහයේදී සප්ත මාත්‍රා තාල 3+4 හෝ 3+2+2 වැනි රටාවන්ගෙන් ගැයේ."),
        q("නව නර්තන නිර්මාණයක් සඳහා 'කතා පිටපත' (Script) සකස් කිරීමේදී පළමුව සැලසුම් කරන්නේ කුමක්ද?", "සිදුවීම් පෙළගැස්ම හා චරිත වර්ධනය", "වේදිකා තිර රෙදිවල මිල ගණන්", "ප්‍රේක්ෂක ආසන අංක පිළිවෙළ", "ආරාධනා පත්‍ර මුද්‍රණය කිරීම", "නැටුමක් මඟින් කතාවක් කියන විට ජවනිකා පෙළගැස්ම පැහැදිලිව සැලසුම් කළ යුතුය."),
        q("වේදිකා නර්තනයකදී 'විකර්ණ රේඛා' (Diagonal lines) මත ශිල්පීන් ගමන් කරවීමෙන් ලැබෙන දෘශ්‍ය වාසිය කුමක්ද?", "වේදිකාවේ ගැඹුර සහ දිග වැඩි කොට පෙන්වීම", "ශිල්පීන් ප්‍රේක්ෂකයාගෙන් සැඟවී යාම", "බෙර හඬ සම්පූර්ණයෙන් අඩු වීම", "වේදිකා ආලෝකය අවම කර ගැනීම", "පසු කෙළවරක සිට ඉදිරි කෙළවරට ගමන් කිරීම වේදිකා අවකාශය පුළුල්ව භාවිත කිරීමට උදව් වේ."),
        q("නර්තන පුහුණු සැසියකදී 'සාමූහික තාල පුහුණුව' මඟින් ශිෂ්‍යයෙකු තුළ ඇතිවන ප්‍රධාන වර්ධනය කුමක්ද?", "සගයන්ගේ රිද්මයට සවන් දී එකඟතාවයෙන් නැටීම", "අනෙක් අයට වඩා වේගයෙන් දිව යාම", "තනිවම බෙර පද වෙනස් කර ගැනීම", "වේදිකාවෙන් පිටත බලා සිටීම", "සමූහ නැටුමේදී එකම තාලය රැකීම සඳහා සෙසු ශිල්පීන් සමඟ සියුම් අවධානයක් තිබිය යුතුය."),
        q("සිංහල ජන නර්තන අංගයක් වන 'ලී කෙළි නැටුම' මඟින් ප්‍රධාන වශයෙන් නිරූපණය වන කලාත්මක ගුණය කුමක්ද?", "ලී කෝටු එකට ගැසීමෙන් උපදින රිද්මය හා එකමුතුකම", "හුදෙකලා ශෝකී හැඟීම් ප්‍රකාශනය", "වෙස්මුහුණු කැපීමේ තාක්ෂණය", "රාත්‍රී දේව ආරාධනා චාරිත්‍රය", "තාලයට ලී දඬු ගසමින් රවුම් හා පේළි මාරු කර නැටීම ගැමි විනෝදාස්වාදය පෙන්වයි."),
        q("ශ්‍රී ලංකාවේ දේශීය නර්තනය පිළිබඳ පර්යේෂණ කළ ප්‍රවීණ විද්වතෙකු වූ මහාචාර්ය එදිරිවීර සරච්චන්ද්‍රයන්ගේ 'මනමේ' නාට්‍යයට බෙහෙවින් ඉවහල් වූයේ කුමන නර්තන අංගයන්ද?", "නාඩගම් නැටුම් පද හා සාම්ප්‍රදායික ශෛලිගත චලන", "බටහිර සම්භාව්‍ය බැලේ පිනුම්", "අප්‍රිකානු ගෝත්‍රික බෙර වාදන", "චීන සර්කස් කරණම් අභ්‍යාස", "මනමේ නාටකය දේශීය නාඩගම් හා සාම්ප්‍රදායික නර්තන සම්ප්‍රදාය නව වේදිකාවට ගෙන ආවේය."),
        q("පාසල් නර්තන කලාගාරයක් පිරිසිදුව හා විධිමත්ව පවත්වා ගැනීම සිසුන්ගේ වගකීමක් වන්නේ ඇයි?", "ආරක්ෂිත පුහුණු පරිසරයක් හා කලා ගෞරවය සුරැකීමට", "පාසලේ වෙනත් ශාස්ත්‍රීය විෂයයන් ඉගෙනීම නැවැත්වීමට", "පාසල් නැටුම් කාමරය ස්ථිරවම වසා තැබීමට", "ප්‍රායෝගික බෙර වාදන අභ්‍යාස අඩු කර ගැනීමට", "පිරිසිදු නැටුම් ශාලාව ශිල්පීන්ගේ සෞඛ්‍යය මෙන්ම සම්ප්‍රදායික විනයද තහවුරු කරයි."),
        q("නර්තනය 'අවකාශය, කාලය සහ ශක්තිය' යන ත්‍රිත්ව සංකල්ප මත පදනම් වන බව පැවසෙන්නේ ඇයි?", "සෑම නැටුම් චලනයක්ම යම් ඉඩක, තාල වේගයක හා ජවයකින් සිදුවන බැවින්", "නැටුම් ප්‍රසංගයක් සඳහා විශාල වේදිකා ශාලා තුනක් අවශ්‍ය වන බැවින්", "සෑම නර්තන අංගයකදීම බෙර වර්ග තුනක් එකවර වැයිය යුතු වන බැවින්", "රංගනය නැරඹීම සඳහා ප්‍රේක්ෂකයන් තිදෙනෙකු පමණක් ප්‍රමාණවත් බැවින්", "Space, Time, Energy යන මූලිකාංග තුන නර්තන නිර්මාණ ශිල්පයේ විශ්වීය පදනම වේ.")
    )
}
